<?php $isEditing=(bool)$editing;$action=$isEditing?url('admin/cms/'.$module.'/'.$editing['id']):url('admin/cms/'.$module);?><div class="page-heading admin-heading"><div><a class="back-link" href="<?= url('admin/cms') ?>">← Website CMS</a><span class="eyebrow">Content module</span><h1><?= e($definition['label']) ?></h1><p>Create, translate, publish and order public website content.</p></div><div class="heading-actions"><?php if($isEditing):?><a class="button button-outline" href="<?= url('admin/cms/'.$module) ?>">Cancel editing</a><?php endif?><a class="button button-primary" href="#editor"><?= $isEditing?'Editing record':'+ New '.$definition['singular'] ?></a></div></div><div class="cms-module-layout"><section class="card cms-records"><div class="card-heading"><div><span class="eyebrow">Published database</span><h2><?= e($definition['label']) ?> records</h2></div><span><?= count($records) ?> item(s)</span></div><div class="table-wrap"><table><thead><tr><th><?= e($definition['singular']) ?></th><th>Status / order</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($records as $record):?><tr><td><b><?= e($record[$definition['title_column']]??'Untitled') ?></b><small class="completion-small"><?= e($record['category']??$record['designation']??$record['album']??'') ?></small></td><td><span class="status-pill status-<?= e($record['status']??'active') ?>"><?= e(ucfirst($record['status']??'active')) ?></span><?php if(isset($record['sort_order'])):?><small class="completion-small">Order <?= e($record['sort_order']) ?></small><?php endif?></td><td><?= format_date($record['updated_at']??$record['created_at'],true) ?></td><td><div class="cms-row-actions"><a class="row-action" href="<?= url('admin/cms/'.$module.'?edit='.$record['id'].'#editor') ?>">✎</a><form method="post" action="<?= url('admin/cms/'.$module.'/'.$record['id'].'/delete') ?>"><?= csrf_field() ?><button class="row-action danger" data-confirm="Delete this <?= e(strtolower($definition['singular'])) ?>? This cannot be undone.">×</button></form></div></td></tr><?php endforeach?></tbody></table><?php if(!$records):?><div class="empty-inline">No records yet. Use the editor to create the first one.</div><?php endif?></div></section><section class="card cms-generic-editor" id="editor"><div class="card-heading"><div><span class="eyebrow"><?= $isEditing?'Update content':'Create content' ?></span><h2><?= e($definition['singular']) ?></h2></div><?php if($isEditing):?><span class="status-pill status-<?= e($editing['status']??'active') ?>"><?= e(ucfirst($editing['status']??'active')) ?></span><?php endif?></div><form method="post" action="<?= $action ?>" enctype="multipart/form-data"><?= csrf_field() ?><div class="editor-language-block"><h3>English source</h3><div class="form-grid"><?php foreach($definition['fields'] as $name=>$field): $type=$field['type'];$value=$editing[$name]??old($name,'');?><label class="<?= in_array($type,['textarea','file'],true)?'full':'' ?>"><?php if($type==='checkbox'):?><span class="check-control"><input type="checkbox" name="<?= e($name) ?>" value="1" <?= checked($value) ?>><span><?= e($field['label']) ?></span></span><?php else:?><span><?= e($field['label']) ?><?= !empty($field['required'])?' *':'' ?></span><?php if($type==='textarea'):?><textarea name="<?= e($name) ?>" rows="<?= $name==='body'||$name==='bio'||$name==='description'?7:4 ?>" <?= !empty($field['required'])?'required':'' ?>><?= e($value) ?></textarea><?php elseif($type==='select'):?><select name="<?= e($name) ?>" <?= !empty($field['required'])?'required':'' ?>><?php foreach($field['options'] as $optionValue=>$optionLabel):?><option value="<?= e($optionValue) ?>"<?= selected($value,$optionValue) ?>><?= e($optionLabel) ?></option><?php endforeach?></select><?php elseif($type==='department'):?><select name="<?= e($name) ?>"><option value="">No department</option><?php foreach($departments as $department):?><option value="<?= e($department['id']) ?>"<?= selected($value,$department['id']) ?>><?= e($department['name']) ?></option><?php endforeach?></select><?php elseif($type==='file'):?><?php $currentPath=!empty($definition['file_column'])?($editing[$definition['file_column']]??''):'';if($currentPath):?><img class="cms-current-image" src="<?= url($currentPath) ?>" alt="Current image"><?php endif?><input type="file" name="image" accept="image/jpeg,image/png,image/webp" <?= !empty($definition['file_required'])&&!$currentPath?'required':'' ?>><small>JPG, PNG or WebP · maximum 6 MB.</small><?php else: $htmlType=in_array($type,['email','date','number'],true)?$type:($type==='datetime'?'datetime-local':'text');$htmlValue=$type==='datetime'&&$value?date('Y-m-d\TH:i',strtotime((string)$value)):$value;?><input type="<?= e($htmlType) ?>" name="<?= e($name) ?>" value="<?= e($htmlValue) ?>" <?= !empty($field['required'])?'required':'' ?>><?php endif?><?php endif?></label><?php endforeach?></div></div><?php foreach(['bn'=>'বাংলা translation','hi'=>'हिन्दी translation'] as $locale=>$languageLabel):?><details class="translation-editor"><summary><?= e($languageLabel) ?> <small>Blank fields use English fallback</small></summary><div class="form-grid"><?php foreach($definition['translatable'] as $fieldName): $meta=$definition['fields'][$fieldName]??['label'=>ucfirst($fieldName),'type'=>'text'];$translated=$translations[$locale][$fieldName]??'';?><label class="<?= ($meta['type']??'')==='textarea'?'full':'' ?>"><span><?= e($meta['label']) ?></span><?php if(($meta['type']??'')==='textarea'):?><textarea name="<?= e($locale.'_'.$fieldName) ?>" rows="4"><?= e($translated) ?></textarea><?php else:?><input name="<?= e($locale.'_'.$fieldName) ?>" value="<?= e($translated) ?>"><?php endif?></label><?php endforeach?></div></details><?php endforeach?><div class="form-actions"><small>All changes are recorded in the audit trail.</small><button class="button button-primary"><?= $isEditing?'Save changes':'Create '.$definition['singular'] ?></button></div></form></section></div>
